 47→/** Build a mock participant object. */
 48→export function mockParticipant(
 49→  overrides: Partial<MockParticipant> = {},
 50→): MockParticipant {
 51→  participantCounter += 1;
 52→  return {
 53→    id: `p-${participantCounter}-${Date.now()}`,
 54→    display_name: overrides.display_name ?? "TestUser",
 55→    role: overrides.role ?? "player",
