 61→/** Derive scenario roles from participant roles. */
 62→function deriveRoles(participants: MockParticipant[]): MockRole[] {
 63→  const seen = new Set<string>();
 64→  const roles: MockRole[] = [];
 65→  for (const p of participants) {
 66→    if (p.role === "game-master" || seen.has(p.role)) continue;
 67→    seen.add(p.role);
 68→    const isDecisionMaker = p.role === "decision_maker" || p.role === "co";
 69→    roles.push({
 70→      id: p.role,
 71→      label: p.role
 72→        .split(/[_-]/)
 73→        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
 74→        .join(" "),
 75→      player_type: isDecisionMaker ? "decision_maker" : "advisor",
 76→    });
 77→  }
 78→  return roles;
 79→}
